using SyWater.Places.Application.Places;using SyWater.Places.Application.Ports.Out;using SyWater.Places.Application.UseCases;using SyWater.Places.Domain.Places;namespace SyWater.Places.Application.Tests;/// <summary>HU-010 (list and switch places) and HU-011 (delete a place).</summary>public class PlaceListSelectDeleteTests{    private readonly InMemoryPlaceRepository _places = new();    private readonly FakeGeographyReader _geography = new();    private readonly FakeDeviceLinkChecker _devices = new();    private readonly FakeClock _clock = new(new DateTimeOffset(2026, 9, 29, 12, 0, 0, TimeSpan.Zero));    private readonly Guid _owner = Guid.NewGuid();    private ListPlacesUseCase List => new(_places, _geography);    private SelectPlaceUseCase Select => new(_places, _geography, _clock);    private DeletePlaceUseCase Delete => new(_places, _devices, _clock);    private async Task<PlaceView> CreatePlace(string name, Guid? owner = null)    {        var view = await new CreatePlaceUseCase(_places, _geography, _clock).ExecuteAsync(            new CreatePlaceCommand(owner ?? _owner, FakeGeographyReader.Bogota.CityId, name,                                   PlaceType.Residential, "Calle 1", null),            CancellationToken.None);        _clock.Advance(TimeSpan.FromMinutes(1));        return view;    }    private Task<IReadOnlyList<PlaceView>> MyPlaces() => List.ExecuteAsync(_owner, CancellationToken.None);    private Task DeletePlace(Guid placeId, Guid? owner = null) =>        Delete.ExecuteAsync(owner ?? _owner, placeId, CancellationToken.None);    // ── HU-010: list ─────────────────────────────────────────────────    [Fact]    public async Task New_user_has_an_empty_list()    {        Assert.Empty(await MyPlaces());    }    [Fact]    public async Task List_shows_only_my_places_with_the_selected_one_first()    {        var casa = await CreatePlace("Casa");        var finca = await CreatePlace("Finca");        await CreatePlace("Ajeno", owner: Guid.NewGuid());        await Select.ExecuteAsync(_owner, finca.Id, CancellationToken.None);        var list = await MyPlaces();        Assert.Equal(2, list.Count);        Assert.Equal(finca.Id, list[0].Id);        Assert.True(list[0].IsDefault);        Assert.Equal(casa.Id, list[1].Id);        Assert.Equal("Bogotá, D.C.", list[1].CityName);    }    // ── HU-010: switch ───────────────────────────────────────────────    [Fact]    public async Task Selecting_a_place_moves_the_default_and_only_one_stays_selected()    {        var casa = await CreatePlace("Casa");        var finca = await CreatePlace("Finca");        var selected = await Select.ExecuteAsync(_owner, finca.Id, CancellationToken.None);        Assert.True(selected.IsDefault);        var list = await MyPlaces();        Assert.Single(list.Where(p => p.IsDefault));        Assert.False(list.Single(p => p.Id == casa.Id).IsDefault);    }    [Fact]    public async Task Selecting_the_place_that_is_already_selected_does_not_write()    {        var casa = await CreatePlace("Casa");        var selected = await Select.ExecuteAsync(_owner, casa.Id, CancellationToken.None);        Assert.True(selected.IsDefault);        Assert.Equal(0, _places.SetDefaultCalls);    }    [Fact]    public async Task Cannot_select_a_place_of_another_owner()    {        var ajeno = await CreatePlace("Ajeno", owner: Guid.NewGuid());        await Assert.ThrowsAsync<PlaceNotFoundException>(() =>            Select.ExecuteAsync(_owner, ajeno.Id, CancellationToken.None));        Assert.Equal(0, _places.SetDefaultCalls);    }    // ── HU-011: delete ───────────────────────────────────────────────    [Fact]    public async Task Deleting_a_place_hides_it_but_keeps_the_row()    {        await CreatePlace("Casa");        var finca = await CreatePlace("Finca");        await DeletePlace(finca.Id);        Assert.Single(await MyPlaces());        Assert.Equal(2, _places.Items.Count);   // soft delete: the row is still there        await Assert.ThrowsAsync<PlaceNotFoundException>(() =>            new GetPlaceUseCase(_places, _geography).ExecuteAsync(_owner, finca.Id, CancellationToken.None));    }    [Fact]    public async Task Deleting_the_selected_place_selects_the_oldest_remaining_one()    {        var casa = await CreatePlace("Casa");       // default        var finca = await CreatePlace("Finca");        await CreatePlace("Local");        await DeletePlace(casa.Id);        var list = await MyPlaces();        Assert.Equal(finca.Id, list[0].Id);        Assert.True(list[0].IsDefault);        Assert.Single(list.Where(p => p.IsDefault));    }    [Fact]    public async Task Deleting_the_last_place_leaves_the_user_without_places()    {        var casa = await CreatePlace("Casa");        await DeletePlace(casa.Id);        Assert.Empty(await MyPlaces());        // and the next place created is the default again (HU-009 rule)        Assert.True((await CreatePlace("Nueva")).IsDefault);    }    [Fact]    public async Task A_place_with_a_device_cannot_be_deleted()    {        var casa = await CreatePlace("Casa");        _devices.PlacesWithDevice.Add(casa.Id);        await Assert.ThrowsAsync<PlaceHasActiveDeviceException>(() => DeletePlace(casa.Id));        Assert.Single(await MyPlaces());        Assert.Empty(_places.Activity);    }    [Fact]    public async Task If_device_service_is_down_nothing_is_deleted()    {        var casa = await CreatePlace("Casa");        _devices.IsDown = true;        await Assert.ThrowsAsync<ExternalServiceUnavailableException>(() => DeletePlace(casa.Id));        Assert.Single(await MyPlaces());    }    [Fact]    public async Task The_deletion_is_logged()    {        var casa = await CreatePlace("Casa");        var finca = await CreatePlace("Finca");        await DeletePlace(casa.Id);        var entry = Assert.Single(_places.Activity);        Assert.Equal(PlaceActivity.PlaceDeleted, entry.Action);        Assert.Equal(casa.Id, entry.PlaceId);        Assert.Equal(_owner, entry.OwnerId);        Assert.Contains("\"name\":\"Casa\"", entry.Metadata);        Assert.Contains(finca.Id.ToString(), entry.Metadata);    }    [Fact]    public async Task Cannot_delete_a_place_of_another_owner_or_twice()    {        var casa = await CreatePlace("Casa");        await Assert.ThrowsAsync<PlaceNotFoundException>(() => DeletePlace(casa.Id, owner: Guid.NewGuid()));        await DeletePlace(casa.Id);        await Assert.ThrowsAsync<PlaceNotFoundException>(() => DeletePlace(casa.Id));        Assert.Single(_places.Activity);    }}